/* Module alimente : deploiement edge lexwallet.app / delegal.dev / lextrust.cloud, endpoints POS et liaison 2-pos-edge/index.html */
const DEFAULT_MAX_BYTES = 131072;
const DEFAULT_TIMEOUT_MS = 4000;
const EMBEDDED_POS_B64 = "";

function toPositiveInt(val, fallback) {
  const n = Number(val);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

function jsonResponse(bodyObj, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(bodyObj), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      ...extraHeaders,
    },
  });
}

function htmlResponse(htmlStr, status = 200) {
  return new Response(htmlStr, {
    status,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}

function decodeEmbeddedPosHtml() {
  if (!EMBEDDED_POS_B64) return null;
  try {
    const bin = atob(EMBEDDED_POS_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return new TextDecoder("utf-8").decode(bytes);
  } catch (_) {
    return null;
  }
}

async function readBoundedJson(request, maxBytes) {
  const contentLength = Number(request.headers.get("content-length") || "0");
  if (Number.isFinite(contentLength) && contentLength > maxBytes) {
    return { ok: false, error: "PAYLOAD_TOO_LARGE", maxBytes };
  }
  const raw = await request.text();
  const byteSize = new TextEncoder().encode(raw).length;
  if (byteSize > maxBytes) {
    return { ok: false, error: "PAYLOAD_TOO_LARGE", maxBytes };
  }
  if (!raw.trim()) {
    return { ok: true, data: {} };
  }
  try {
    return { ok: true, data: JSON.parse(raw) };
  } catch (_) {
    return { ok: false, error: "INVALID_JSON" };
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const host = (request.headers.get("host") || url.hostname || "").toLowerCase().split(":")[0];
    const maxBytes = toPositiveInt(env && env.MAX_PAYLOAD_BYTES, DEFAULT_MAX_BYTES);
    const timeoutMs = toPositiveInt(env && env.REQUEST_TIMEOUT_MS, DEFAULT_TIMEOUT_MS);
    const primaryDomain = (env && env.PRIMARY_DOMAIN) || "lexwallet.app";
    const allowedDomains = String((env && env.DOMAINS_ALLOWED) || "lexwallet.app,delegal.dev,lextrust.cloud")
      .split(",")
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    const tenantId = (env && env.TENANT_ID) || "CHEER-FLAGSHIP-01";
    const adminEmail = (env && env.ADMIN_EMAIL) || "cbltec@proton.me";
    const appEnv = (env && env.APP_ENV) || "production";

    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type",
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname === "/health") {
      return jsonResponse({
        status: "ok",
        service: "cheer-tec-pos-worker",
        env: appEnv,
        host,
        primaryDomain,
        allowedDomains,
        tenantId,
        adminEmail,
        timeoutMs,
        maxBytes,
        ts: new Date().toISOString(),
      });
    }

    if (url.pathname === "/api/pos/meta") {
      return jsonResponse({
        primaryDomain,
        allowedDomains,
        tenantId,
        adminEmail,
        posRoute: "#/POS/caisse",
        engineVersion: "V14.0",
        maxBytes,
        timeoutMs,
      });
    }

    if (url.pathname === "/api/pos/sync") {
      if (request.method !== "POST") {
        return jsonResponse({ ok: false, error: "METHOD_NOT_ALLOWED" }, 405);
      }
      const parsed = await readBoundedJson(request, maxBytes);
      if (!parsed.ok) {
        const code = parsed.error === "PAYLOAD_TOO_LARGE" ? 413 : 400;
        return jsonResponse({ ok: false, error: parsed.error, maxBytes }, code);
      }
      const payload = parsed.data && typeof parsed.data === "object" ? parsed.data : {};
      return jsonResponse({
        ok: true,
        accepted: true,
        host,
        primaryDomain,
        tenantId,
        adminEmail,
        receivedKeys: Object.keys(payload),
        ts: new Date().toISOString(),
      });
    }

    if (host.includes("delegal.dev") || url.pathname.startsWith("/delegal")) {
      return jsonResponse({
        ok: true,
        domain: "delegal.dev",
        module: "delegal-service",
        adminEmail,
        status: "active",
      });
    }

    if (host.includes("lextrust.cloud") || url.pathname.startsWith("/trust")) {
      return jsonResponse({
        ok: true,
        domain: "lextrust.cloud",
        module: "lextrust-audit",
        adminEmail,
        status: "active",
      });
    }

    if (request.method === "GET" && (url.pathname === "/" || url.pathname === "/index.html" || url.pathname.startsWith("/pos"))) {
      if (env && env.ASSETS && typeof env.ASSETS.fetch === "function") {
        const assetRes = await env.ASSETS.fetch(request);
        if (assetRes && assetRes.status !== 404) {
          return new Response(assetRes.body, {
            status: assetRes.status,
            headers: {
              ...Object.fromEntries(assetRes.headers.entries()),
              "Cache-Control": "no-store",
            },
          });
        }
      }
      const decoded = decodeEmbeddedPosHtml();
      if (decoded) {
        return htmlResponse(decoded, 200);
      }
      return htmlResponse(
        "<!doctype html><html><head><meta charset='utf-8'><title>LexWallet POS</title></head><body><h1>LexWallet POS</h1><p>Tenant: " +
          tenantId +
          " • Admin: " +
          adminEmail +
          "</p></body></html>",
        200
      );
    }

    return jsonResponse(
      {
        ok: false,
        error: "NOT_FOUND",
        path: url.pathname,
        host,
        primaryDomain,
        allowedDomains,
        tenantId,
        adminEmail,
        availableRoutes: ["/", "/health", "/api/pos/meta", "/api/pos/sync", "/delegal", "/trust"],
      },
      404
    );
  },
};
